-- Complete the Cancer Research UK inventory for TfL zones 1-4.
-- Audited against the official CRUK shop finder and current branch listings on 2026-11-06.

















INSERT OR IGNORE INTO place_collections(place_id, collection_code) SELECT id, 'CHARITY_SHOP' FROM places WHERE id IN ('CS-CANCER-RESEARCH-UK-FULHAM','CS-CANCER-RESEARCH-UK-MITCHAM','CS-CANCER-RESEARCH-UK-BECKENHAM','CS-CANCER-RESEARCH-UK-RICHMOND','CS-CANCER-RESEARCH-UK-NEW-MALDEN','CS-CANCER-RESEARCH-UK-ILFORD','CS-CANCER-RESEARCH-UK-GREENFORD','CS-CANCER-RESEARCH-UK-HOUNSLOW');


